import itertools, math
from functools import lru_cache

# ---------- Laurent polynomials over GF(2) as frozensets of (a,b) ----------
def O(a,b):
    return frozenset({(a,b),(-a,b),(a,-b),(-a,-b),(b,a),(-b,a),(b,-a),(-b,-a)})
def add(p,q): return p ^ q
def mul(p,q):
    r=set()
    for (a,b) in p:
        for (c,d) in q:
            r ^= {(a+c,b+d)}
    return frozenset(r)
def powp(p,k):
    r=frozenset({(0,0)})
    for _ in range(k): r=mul(r,p)
    return r
def t(z):  # z = 'x' or 'y' or (a,b) monomial exponent
    return frozenset({z,(-z[0],-z[1])})
X=(1,0); Y=(0,1)
def mono(a,b): return frozenset({(a,b)})
def redm(p,m):  # reduce mod x^m-1,y^m-1
    r=set()
    for (a,b) in p: r ^= {(a%m,b%m)}
    return frozenset(r)
def dil(p,n): return frozenset({(n*a,n*b) for (a,b) in p})
def dil2(p,n1,n2): return frozenset({(n1*a,n2*b) for (a,b) in p})

ORBS=[(a,b) for a in range(5) for b in range(a+1)]
def rule(n):
    # bit i of n-? assume id = sum 2^i over orbit index i, id from 1..32767
    p=frozenset()
    for i,(a,b) in enumerate(ORBS):
        if (n>>i)&1: p=add(p,O(a,b))
    return p
def orbits_of(p):
    s=set()
    for (a,b) in p:
        a,b=abs(a),abs(b)
        s.add((max(a,b),min(a,b)))
    return sorted(s)

# ---------- GF(2)[x]/Phi_m(x), m prime with 2 primitive ----------
class Fm:
    def __init__(self,m):
        self.m=m; self.d=m-1
        self.mod=(1<<m)-1 >> 0  # Phi_m = 1+x+...+x^{m-1} = (1<<m)-1 as bits
        self.mod=sum(1<<i for i in range(m))
    def red(self,a):
        mod=self.mod; d=self.d
        while a>>d:
            h=a.bit_length()-1
            a ^= mod<<(h-d)
        return a
    def mulf(self,a,b):
        r=0
        while b:
            if b&1: r^=a
            a<<=1; b>>=1
        return self.red(r)
    def powf(self,a,e):
        r=1
        while e:
            if e&1: r=self.mulf(r,a)
            a=self.mulf(a,a); e>>=1
        return r
    def ev(self,p,j,k):
        m=self.m; a=0
        for (u,v) in p: a ^= 1<<((u*j+v*k)%m)
        return self.red(a)
    def order(self,a):
        n=(1<<self.d)-1
        if a==0: return None
        o=n
        for q in sorted(set(factorint(n))):
            while o%q==0 and self.powf(a,o//q)==1: o//=q
        return o
def factorint(n):
    f={}; p=2
    while p*p<=n:
        while n%p==0: f[p]=f.get(p,0)+1; n//=p
        p+=1
    if n>1: f[n]=f.get(n,0)+1
    return f

def classes(m):
    # character classes under <2> x dihedral
    seen=set(); reps=[]
    for j in range(m):
        for k in range(m):
            if (j,k) in seen: continue
            cl=set(); st=[(j,k)]
            while st:
                u,v=st.pop()
                if (u,v) in cl: continue
                cl.add((u,v))
                st += [((2*u)%m,(2*v)%m),(v,u),((-u)%m,v),(u,(-v)%m)]
            seen|=cl; reps.append((j,k,len(cl)))
    return reps

def cube_status(F,p,s):
    """return list of (j,k,size,is_zero,is_cube) over classes"""
    m=F.m; e=((1<<s)-1)//3; out=[]
    for (j,k,sz) in classes(m):
        lam=F.ev(p,j,k)
        if lam==0: out.append((j,k,sz,True,True)); continue
        out.append((j,k,sz,False,F.powf(lam,e)==1))
    return out
def confined(F,p,s):
    return all(c for (_,_,_,_,c) in cube_status(F,p,s))
def fieldsize(F,lam):
    # smallest e with lam^(2^e)=lam
    a=lam
    for e in range(1,F.d+1):
        a=F.mulf(a,a)
        if a==lam: return e

from ca import *
from sympy import Poly, symbols, GF, factor_list
import itertools
xs=symbols('x')

def shift_nonneg(p):
    a0=min(a for a,b in p); b0=min(b for a,b in p)
    return frozenset((a-a0,b-b0) for a,b in p)

def kron(p,N):
    # p set of (a,b) exps nonneg -> univariate int bitmask with x^(a+N b)
    return sum(1<<(a+N*b) for a,b in p)
def unkron(mask,N):
    s=set(); i=0
    while mask:
        if mask&1: s.add((i%N,i//N))
        mask>>=1; i+=1
    return frozenset(s)
def mask_to_poly(mask):
    return Poly([int(c) for c in bin(mask)[2:]], xs, modulus=2)
def poly_to_mask(P):
    cs=P.all_coeffs(); m=0
    for c in cs: m=(m<<1)|(int(c)%2)
    return m
def ufactor(mask):
    P=mask_to_poly(mask)
    _,fl=factor_list(P)
    out=[]
    for f,e in fl:
        out += [poly_to_mask(f)]*e
    return out
def umul(a,b):
    r=0
    while b:
        if b&1: r^=a
        a<<=1; b>>=1
    return r

def bifactor(p):
    """irreducible factorisation of Laurent poly p over GF(2); returns list of (factor set, mult)."""
    p=shift_nonneg(p)
    degx=max(a for a,b in p); 
    N=2*degx+2
    fs=ufactor(kron(p,N))
    # find irreducible bivariate factors by minimal subsets
    def find(p,fs):
        if len(fs)<=1:
            return [p]
        n=len(fs)
        for r in range(1,n):
            for S in itertools.combinations(range(n),r):
                m1=1
                for i in S: m1=umul(m1,fs[i])
                m2=1
                for i in range(n):
                    if i not in S: m2=umul(m2,fs[i])
                q1=unkron(m1,N); q2=unkron(m2,N)
                if mul(q1,q2)==p:
                    return find(q1,[fs[i] for i in S]) + find(q2,[fs[i] for i in range(n) if i not in S])
        return [p]
    facs=find(p,fs)
    out={}
    for f in facs:
        f=shift_nonneg(f)
        out[f]=out.get(f,0)+1
    return sorted(out.items(), key=lambda kv:(len(kv[0]),sorted(kv[0])))

def show(p):
    terms=[]
    for a,b in sorted(p):
        s=''
        if a: s+='x' if a==1 else 'x^%d'%a
        if b: s+=('*' if s else '')+('y' if b==1 else 'y^%d'%b)
        terms.append(s or '1')
    return '+'.join(terms)

